"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["204"],{6213(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>p,frontMatter:()=>s,contentTitle:()=>r,toc:()=>c,assets:()=>l});var i=JSON.parse('{"id":"networks/stp","title":"Spanning Tree Protocol","description":"Spanning Tree Protocol (STP) prevents Layer 2 loops in switched networks with redundant physical links \u2014 a deceptively simple-sounding problem that, if unsolved, causes catastrophic broadcast storms capable of taking down an entire network within seconds.","source":"@site/docs/networks/14-stp.md","sourceDirName":"networks","slug":"/networks/stp","permalink":"/Mindstack/docs/networks/stp","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":14,"frontMatter":{"title":"Spanning Tree Protocol","sidebar_label":"Spanning Tree (STP)","sidebar_position":14},"sidebar":"networkSidebar","previous":{"title":"vlans","permalink":"/Mindstack/docs/networks/vlans"},"next":{"title":"EtherChannel","permalink":"/Mindstack/docs/networks/etherchannel"}}'),o=t(4848),a=t(8453);let s={title:"Spanning Tree Protocol",sidebar_label:"Spanning Tree (STP)",sidebar_position:14},r="Spanning Tree Protocol",l={},c=[{value:"Why Redundant Links Cause Catastrophic Problems at Layer 2",id:"why-redundant-links-cause-catastrophic-problems-at-layer-2",level:2},{value:"History of Spanning Tree",id:"history-of-spanning-tree",level:2},{value:"How STP Builds a Loop-Free Tree",id:"how-stp-builds-a-loop-free-tree",level:2},{value:"STP Port States (802.1D Classic)",id:"stp-port-states-8021d-classic",level:2},{value:"BPDUs \u2014 Bridge Protocol Data Units",id:"bpdus--bridge-protocol-data-units",level:2},{value:"RSTP \u2014 Rapid Spanning Tree Protocol (802.1w)",id:"rstp--rapid-spanning-tree-protocol-8021w",level:2},{value:"MSTP \u2014 Multiple Spanning Tree Protocol (802.1s)",id:"mstp--multiple-spanning-tree-protocol-8021s",level:2},{value:"STP Protection Features",id:"stp-protection-features",level:2},{value:"Configuration Example (Cisco IOS)",id:"configuration-example-cisco-ios",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"spanning-tree-protocol",children:"Spanning Tree Protocol"})}),"\n",(0,o.jsx)(n.p,{children:"Spanning Tree Protocol (STP) prevents Layer 2 loops in switched networks with redundant physical links \u2014 a deceptively simple-sounding problem that, if unsolved, causes catastrophic broadcast storms capable of taking down an entire network within seconds."}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"why-redundant-links-cause-catastrophic-problems-at-layer-2",children:"Why Redundant Links Cause Catastrophic Problems at Layer 2"}),"\n",(0,o.jsx)(n.p,{children:"Physical link redundancy is good for availability \u2014 but unlike Layer 3 (where routing protocols inherently understand topology and avoid loops via metrics/hop counts), raw Layer 2 switching has NO loop prevention built in by default."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'The Loop Problem:\n        [Switch A]\n        /        \\\n   [Switch B]\u2500\u2500[Switch C]\n\nIf Switch A, B, and C are connected in this redundant triangle WITHOUT\nspanning tree, a single broadcast frame (e.g. an ARP request) entering\nthis topology gets FLOODED out every port by EVERY switch (recall:\nswitches flood broadcasts \u2014 see Switching Fundamentals) \u2014 and because\nthe topology has a loop, that same frame circulates endlessly,\ngetting duplicated and re-flooded at every switch, every cycle.\n\nWithin seconds, this exponential duplication consumes 100% of available\nbandwidth and CPU on every involved switch \u2014 a "broadcast storm" \u2014 and\nthe network becomes completely unusable until the loop is physically\nbroken. MAC address tables also become unstable, with switches seeing\nthe same source MAC arrive on multiple ports in rapid succession\n(MAC flapping), unable to converge on a consistent forwarding decision.\n'})}),"\n",(0,o.jsxs)(n.p,{children:["This is precisely why blindly adding redundant links to a switched network is actively dangerous without a loop-prevention protocol \u2014 STP exists specifically to allow the ",(0,o.jsx)(n.em,{children:"physical"})," redundancy (for resilience) while preventing the ",(0,o.jsx)(n.em,{children:"logical"})," loop (which would otherwise be catastrophic)."]}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"history-of-spanning-tree",children:"History of Spanning Tree"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'1985 \u2014 Radia Perlman develops the original Spanning Tree algorithm at\n       Digital Equipment Corporation (DEC), famously summarized in a\n       playful poem she wrote: "I think that I shall never see / A\n       graph more lovely than a tree..." \u2014 DEC\'s proprietary version\n       predates the IEEE standard\n\n1990 \u2014 IEEE standardizes 802.1D, codifying STP as an industry standard\n       (convergence time: up to 30-50 seconds \u2014 slow by modern standards,\n       a real operational pain point through the 1990s)\n\n2001 \u2014 IEEE 802.1w standardizes Rapid Spanning Tree Protocol (RSTP),\n       dramatically improving convergence time (typically under a few\n       seconds) by rethinking port states and adding direct\n       switch-to-switch negotiation instead of relying purely on timers\n\n2002-03 \u2014 IEEE 802.1s standardizes Multiple Spanning Tree Protocol\n          (MSTP), allowing multiple spanning tree instances to map to\n          different groups of VLANs, enabling load balancing across\n          redundant links instead of single STP\'s "one tree fits all\n          VLANs" limitation\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"how-stp-builds-a-loop-free-tree",children:"How STP Builds a Loop-Free Tree"}),"\n",(0,o.jsxs)(n.p,{children:["STP's fundamental approach: elect a ",(0,o.jsx)(n.strong,{children:"root bridge"}),", then have every other switch calculate the single best (lowest-cost) path back to that root, and ",(0,o.jsx)(n.strong,{children:"block"})," any redundant port that would otherwise create a loop \u2014 while keeping that blocked link in reserve, ready to activate automatically if the active path fails."]}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'Step 1 \u2014 Root Bridge Election:\n  Every switch has a Bridge ID = Bridge Priority (default 32768) + MAC\n  address. The switch with the LOWEST Bridge ID becomes the Root Bridge\n  \u2014 the single reference point the entire tree is built around.\n  (Lower priority value wins; ties broken by lowest MAC address.)\n\nStep 2 \u2014 Root Port Selection (on every NON-root switch):\n  Each non-root switch selects exactly ONE Root Port \u2014 the port with\n  the lowest-cost path back to the root bridge. Cost is based on link\n  speed (lower cost = faster link, see table below).\n\nStep 3 \u2014 Designated Port Selection (per network segment):\n  For each LAN segment, exactly one switch becomes "designated" for\n  that segment (usually whichever switch is closer to the root, or\n  has the lowest Bridge ID in a tie) and its port stays in forwarding state.\n\nStep 4 \u2014 Blocking:\n  Any port that is NEITHER a Root Port NOR a Designated Port is placed\n  into BLOCKING state \u2014 it physically still exists and is ready to\n  activate, but does not forward any data frames, eliminating the loop.\n'})}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'STP Path Cost (IEEE 802.1D original / 802.1t revised, by link speed):\n10 Mbps    \u2192 cost 100\n100 Mbps   \u2192 cost 19\n1 Gbps     \u2192 cost 4\n10 Gbps    \u2192 cost 2\n(Lower cost = preferred path \u2014 faster links are "cheaper" in STP math)\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"stp-port-states-8021d-classic",children:"STP Port States (802.1D Classic)"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"Blocking   \u2014 does not forward frames, listens for BPDUs only (loop prevention)\nListening  \u2014 transitioning toward forwarding, listens for BPDUs, builds\n             active topology understanding, still does NOT forward data\nLearning   \u2014 begins learning MAC addresses into the table, still does\n             NOT forward data\nForwarding \u2014 fully active, forwards data AND learns MAC addresses\nDisabled   \u2014 administratively shut down\n\nClassic 802.1D STP convergence (moving through these states after a\ntopology change) could take 30-50 seconds \u2014 a significant, often\nbusiness-impacting delay in an era before RSTP.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"bpdus--bridge-protocol-data-units",children:"BPDUs \u2014 Bridge Protocol Data Units"}),"\n",(0,o.jsxs)(n.p,{children:["Switches exchange ",(0,o.jsx)(n.strong,{children:"BPDUs"})," to communicate Bridge IDs, path costs, and topology information, enabling the entire root-election and port-role-assignment process described above."]}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"BPDUs are sent as multicast frames (destination MAC 01:80:C2:00:00:00)\nevery 2 seconds by default (the \"Hello Timer\"), allowing switches to\ncontinuously verify the topology is stable and to detect failures.\n\nKey BPDU fields:\n  Root Bridge ID    \u2014 who the sender believes is currently the root\n  Sender Bridge ID  \u2014 the sending switch's own Bridge ID\n  Root Path Cost    \u2014 the sender's cumulative cost to reach the root\n  Timers            \u2014 Hello Time, Max Age, Forward Delay\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"rstp--rapid-spanning-tree-protocol-8021w",children:"RSTP \u2014 Rapid Spanning Tree Protocol (802.1w)"}),"\n",(0,o.jsx)(n.p,{children:"RSTP is the modern default on virtually all current switching equipment, providing dramatically faster convergence by reworking both the port state model and the underlying signaling mechanism."}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'RSTP Port States (simplified from 5 to 3):\n  Discarding  \u2014 combines classic STP\'s Blocking AND Listening states\n  Learning    \u2014 same concept as classic STP\n  Forwarding  \u2014 same concept as classic STP\n\nRSTP Port Roles (new concept, beyond classic STP\'s Root/Designated/Blocked):\n  Root Port        \u2014 same as classic STP\n  Designated Port  \u2014 same as classic STP\n  Alternate Port   \u2014 a backup path to the root, ready to take over almost\n                     instantly if the root port fails (this is the\n                     conceptual replacement for "blocked," but actively\n                     pre-computed and ready rather than purely passive)\n  Backup Port      \u2014 a backup for a designated port on the SAME segment\n                     (relevant when a switch has two links to the same\n                     shared segment, a less common scenario)\n\nWhy RSTP is so much faster: instead of relying primarily on fixed\ntimers (waiting out the Listening/Learning delay), RSTP switches\nactively exchange explicit handshake messages ("proposal/agreement")\nwith neighboring switches to rapidly confirm new port roles, achieving\nsub-second to low-single-digit-second convergence in most real\ntopologies \u2014 a dramatic practical improvement over classic 802.1D\'s\n30-50 second convergence.\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"mstp--multiple-spanning-tree-protocol-8021s",children:"MSTP \u2014 Multiple Spanning Tree Protocol (802.1s)"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"Problem MSTP solves: classic STP and RSTP compute exactly ONE spanning\ntree for the ENTIRE switched network, regardless of how many VLANs\nexist. This means ALL VLANs share the same blocked/forwarding link\ndecisions \u2014 even if it would be more efficient to forward VLAN 10's\ntraffic over Link A while forwarding VLAN 20's traffic over Link B\n(load balancing the redundant links instead of leaving one entirely idle).\n\nMSTP allows mapping GROUPS of VLANs to separate \"MST instances,\" each\nwith its own independently-computed spanning tree \u2014 enabling genuine\nload balancing across redundant links rather than always leaving one\nlink 100% idle in blocking state for every VLAN simultaneously.\n\nCisco's proprietary PVST+ (Per-VLAN Spanning Tree Plus) and Rapid\nPVST+ achieve a SIMILAR practical outcome (a separate STP instance\nPER VLAN, rather than grouped instances like MSTP) and are extremely\ncommon in real Cisco deployments \u2014 worth knowing as the most likely\nSTP variant you'll actually encounter on Cisco gear in practice,\neven though MSTP is the open IEEE standard.\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"stp-protection-features",children:"STP Protection Features"}),"\n",(0,o.jsx)(n.p,{children:"Beyond the base protocol, several widely-deployed features harden STP against common real-world misconfiguration and edge cases:"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:'PortFast \u2014 applied to ACCESS ports connecting to end devices (PCs,\n  servers) ONLY. Skips the Listening/Learning delay entirely, moving\n  straight to Forwarding, since end devices don\'t create loops and\n  shouldn\'t have to wait 30+ seconds after a reboot just to get an IP\n  via DHCP. NEVER enable PortFast on a port that connects to another\n  switch \u2014 doing so risks a real loop if that "end device" port ever\n  actually receives a BPDU from an accidentally-connected switch.\n\nBPDU Guard \u2014 applied alongside PortFast: if a port configured for\n  PortFast EVER receives a BPDU (meaning a switch, not an end device,\n  is actually connected there \u2014 perhaps an employee plugged in a\n  cheap unmanaged switch/hub creating an accidental loop), the port is\n  immediately disabled (err-disabled), preventing the very loop\n  scenario PortFast\'s assumption was designed around.\n\nRoot Guard \u2014 applied on a port to prevent a downstream/unexpected\n  switch from becoming the root bridge \u2014 if a superior BPDU (one that\n  would normally win root election) is received on a Root-Guard-\n  protected port, that port is put into a "root-inconsistent" state\n  instead of allowing the topology to be hijacked.\n\nLoop Guard \u2014 protects against a specific failure mode where a port\n  stops receiving BPDUs (e.g. due to a unidirectional link failure)\n  and incorrectly transitions to forwarding, potentially creating a\n  loop \u2014 Loop Guard keeps such a port in a blocking state instead\n  until BPDUs resume.\n\nBPDU Filter \u2014 suppresses BPDU transmission/processing on a port\n  entirely (different from BPDU Guard, which reacts to BPDU arrival\n  by disabling the port) \u2014 used more rarely and more carefully, as\n  misuse can itself create loop vulnerabilities.\n'})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"configuration-example-cisco-ios",children:"Configuration Example (Cisco IOS)"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{children:"! Enable Rapid PVST+ (per-VLAN RSTP) globally\nSwitch(config)# spanning-tree mode rapid-pvst\n\n! Influence root bridge election (lower priority = more likely to be root)\nSwitch(config)# spanning-tree vlan 10 priority 4096\n! Or, simpler: force this switch to be root for VLAN 10\nSwitch(config)# spanning-tree vlan 10 root primary\n\n! PortFast + BPDU Guard on an access port\nSwitch(config)# interface gigabitethernet 0/5\nSwitch(config-if)# spanning-tree portfast\nSwitch(config-if)# spanning-tree bpduguard enable\n\n! Root Guard on an uplink port that should NEVER become a root port\nSwitch(config)# interface gigabitethernet 0/24\nSwitch(config-if)# spanning-tree guard root\n\n! Verification\nSwitch# show spanning-tree\nSwitch# show spanning-tree vlan 10\nSwitch# show spanning-tree interface gi0/1 detail\n"})}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"Never enable PortFast on a switch-to-switch (trunk) port \u2014 pair PortFast with BPDU Guard on access ports specifically, and treat any err-disabled port (caused by BPDU Guard firing) as a strong signal someone plugged in an unauthorized switch/hub."}),"\n",(0,o.jsxs)(n.li,{children:["When designing redundant Layer 2 topologies today, strongly consider whether STP is even the right tool \u2014 many modern datacenter designs avoid Layer 2 loops architecturally (e.g. via Layer 3 leaf-spine designs or technologies like VXLAN/EVPN \u2014 see VXLAN & Modern L2) rather than relying on STP's loop ",(0,o.jsx)(n.em,{children:"tolerance"})," via blocking."]}),"\n",(0,o.jsx)(n.li,{children:"If troubleshooting intermittent, severe network slowdowns that resolve themselves after a port flaps, suspect a Layer 2 loop or an STP misconfiguration (e.g. an unintended root bridge change) before assuming a Layer 3 or application-level cause."}),"\n"]}),"\n",(0,o.jsx)(n.hr,{}),"\n",(0,o.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"STP exists because raw Layer 2 switching has no native loop prevention \u2014 a physical loop without STP causes a broadcast storm capable of taking down an entire network within seconds."}),"\n",(0,o.jsx)(n.li,{children:"Classic 802.1D STP (Radia Perlman, 1985, standardized 1990) elects a root bridge, computes shortest paths, and blocks redundant ports \u2014 but converges slowly (30-50 seconds)."}),"\n",(0,o.jsx)(n.li,{children:"RSTP (802.1w, 2001) dramatically improves convergence (sub-second to low seconds) via active proposal/agreement handshakes and a simplified port state model."}),"\n",(0,o.jsx)(n.li,{children:"MSTP (and Cisco's PVST+/Rapid PVST+) allow per-VLAN or per-VLAN-group spanning trees, enabling load balancing across redundant links instead of always idling one link entirely."}),"\n",(0,o.jsx)(n.li,{children:"PortFast + BPDU Guard is the standard hardening pattern for access ports; Root Guard and Loop Guard protect against specific topology-hijacking and unidirectional-link failure scenarios respectively."}),"\n",(0,o.jsx)(n.li,{children:"Modern network designs increasingly avoid Layer 2 loops architecturally rather than relying purely on STP's tolerate-and-block approach."}),"\n"]})]})}function p(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(6540);let o={},a=i.createContext(o);function s(e){let n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);